  /** Removed. */
  gone_since?: TimeFilterInput | null | undefined;
  /** Kind. */
  kind?: KindFilterInput | null | undefined;
  /** Last changed. */
  last_changed?: TimeFilterInput | null | undefined;
  /** Last seen. */
  last_seen?: TimeFilterInput | null | undefined;
  /** Notes. */
  notes?: TextFilterInput | null | undefined;
  /** Verdict reason (Verdict). */
  reason?: TextFilterInput | null | undefined;
  /** Senior only. */
  senior_only?: BoolFilterInput | null | undefined;
  /** Source. */
  source?: TextFilterInput | null | undefined;
  /** Status. */
  status?: PublishedStatusFilterInput | null | undefined;
  /** Title. */
  title?: TextFilterInput | null | undefined;
  /** Units (Verdict). */
  unit_count?: NumberFilterInput | null | undefined;
  /** A listing matches when one of its units meets every condition here together. */
  units?: UnitFilterInput | null | undefined;
